import{_ as o,o as d,c,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"JavaScript 标准库 API 总索引","description":"","frontmatter":{"title":"JavaScript 标准库 API 总索引","outline":[2,3]},"headers":[],"relativePath":"frontend/guide/core/javascript/standard-library.md","filePath":"frontend/guide/core/javascript/standard-library.md","lastUpdated":1784378817000}'),t={name:"frontend/guide/core/javascript/standard-library.md"};function l(i,e,r,n,s,h){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="javascript-标准库-api-总索引" tabindex="-1">JavaScript 标准库 API 总索引 <a class="header-anchor" href="#javascript-标准库-api-总索引" aria-label="Permalink to &quot;JavaScript 标准库 API 总索引&quot;">​</a></h1><p>本页汇总 ECMAScript 标准内置对象、属性和方法，基线为 ECMAScript 2026。适合通过站内搜索或浏览器页内搜索快速定位 API。</p><p>这里不包含 DOM、<code>fetch()</code>、<code>console</code>、定时器、<code>structuredClone()</code> 等 Web API，也不包含 Node.js 全局对象。尚未进入 ECMAScript 标准的 TC39 提案不会作为稳定 API 收录。不同浏览器和运行时的实现进度可能不同，使用较新 API 前仍需检查兼容性。</p><h2 id="阅读约定" tabindex="-1">阅读约定 <a class="header-anchor" href="#阅读约定" aria-label="Permalink to &quot;阅读约定&quot;">​</a></h2><ul><li>“静态”表示通过构造器或命名空间调用，例如 <code>Array.from()</code>。</li><li>“实例”表示通过具体值调用，例如 <code>array.map()</code>。</li><li>所有原型共有的 <code>constructor</code>，以及从 <code>Object.prototype</code> 继承的成员不重复列出。</li><li><code>[Symbol.xxx]</code> 表示以知名 Symbol 为键的协议成员。</li><li>“已弃用”成员仅用于维护旧代码，不应出现在新代码中。</li></ul><h2 id="详细章节" tabindex="-1">详细章节 <a class="header-anchor" href="#详细章节" aria-label="Permalink to &quot;详细章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>重点</th></tr></thead><tbody><tr><td><a href="/frontend/guide/core/javascript/standard-library/fundamentals">Object、Function、Symbol 与错误对象</a></td><td>属性、原型、调用、语言协议与错误模型</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/arrays-typed-arrays">Array、TypedArray 与数组操作</a></td><td>序列操作、稀疏数组、二进制数值视图</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/maps-sets">Map、Set 与弱引用集合</a></td><td>键值集合、集合运算与生命周期关联</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/text-json">String、RegExp 与 JSON</a></td><td>Unicode、模式匹配与序列化</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/numbers-math">Number、BigInt 与 Math</a></td><td>数值精度、整数边界与数学 API</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/binary-data">ArrayBuffer、DataView 与 Atomics</a></td><td>字节、大小端、共享内存与原子操作</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/date-temporal-intl">Date、Temporal 与 Intl</a></td><td>时间模型、时区、日历与国际化</td></tr><tr><td><a href="/frontend/guide/core/javascript/standard-library/async-iteration-resources">Promise、Iterator、Generator 与资源管理</a></td><td>异步组合、惰性序列和确定性释放</td></tr></tbody></table><h2 id="全局值与全局函数" tabindex="-1">全局值与全局函数 <a class="header-anchor" href="#全局值与全局函数" aria-label="Permalink to &quot;全局值与全局函数&quot;">​</a></h2><h3 id="全局值" tabindex="-1">全局值 <a class="header-anchor" href="#全局值" aria-label="Permalink to &quot;全局值&quot;">​</a></h3><ul><li><code>globalThis</code></li><li><code>Infinity</code></li><li><code>NaN</code></li><li><code>undefined</code></li></ul><h3 id="全局函数" tabindex="-1">全局函数 <a class="header-anchor" href="#全局函数" aria-label="Permalink to &quot;全局函数&quot;">​</a></h3><ul><li>求值与数值：<code>eval()</code>、<code>isFinite()</code>、<code>isNaN()</code>、<code>parseFloat()</code>、<code>parseInt()</code></li><li>URI 编解码：<code>decodeURI()</code>、<code>decodeURIComponent()</code>、<code>encodeURI()</code>、<code>encodeURIComponent()</code></li><li>已弃用：<code>escape()</code>、<code>unescape()</code></li></ul><p>优先使用 <code>Number.isFinite()</code> 和 <code>Number.isNaN()</code>，它们不会先执行隐式数值转换。<code>eval()</code> 会扩大安全、性能和静态分析风险，应避免用于普通业务逻辑。</p><h2 id="基础对象" tabindex="-1">基础对象 <a class="header-anchor" href="#基础对象" aria-label="Permalink to &quot;基础对象&quot;">​</a></h2><h3 id="object" tabindex="-1"><code>Object</code> <a class="header-anchor" href="#object" aria-label="Permalink to &quot;`Object`&quot;">​</a></h3><ul><li>构造：<code>Object()</code></li><li>静态创建与复制：<code>Object.assign()</code>、<code>Object.create()</code>、<code>Object.fromEntries()</code></li><li>静态属性描述：<code>Object.defineProperty()</code>、<code>Object.defineProperties()</code>、<code>Object.getOwnPropertyDescriptor()</code>、<code>Object.getOwnPropertyDescriptors()</code>、<code>Object.getOwnPropertyNames()</code>、<code>Object.getOwnPropertySymbols()</code></li><li>静态枚举：<code>Object.entries()</code>、<code>Object.keys()</code>、<code>Object.values()</code></li><li>静态原型操作：<code>Object.getPrototypeOf()</code>、<code>Object.setPrototypeOf()</code></li><li>静态完整性控制：<code>Object.freeze()</code>、<code>Object.seal()</code>、<code>Object.preventExtensions()</code>、<code>Object.isFrozen()</code>、<code>Object.isSealed()</code>、<code>Object.isExtensible()</code></li><li>静态判断与分组：<code>Object.hasOwn()</code>、<code>Object.is()</code>、<code>Object.groupBy()</code></li><li>实例方法：<code>hasOwnProperty()</code>、<code>isPrototypeOf()</code>、<code>propertyIsEnumerable()</code>、<code>toLocaleString()</code>、<code>toString()</code>、<code>valueOf()</code></li><li>已弃用实例成员：<code>__defineGetter__()</code>、<code>__defineSetter__()</code>、<code>__lookupGetter__()</code>、<code>__lookupSetter__()</code>、<code>__proto__</code></li></ul><h3 id="function" tabindex="-1"><code>Function</code> <a class="header-anchor" href="#function" aria-label="Permalink to &quot;`Function`&quot;">​</a></h3><ul><li>构造：<code>Function()</code></li><li>实例属性：<code>length</code>、<code>name</code>、<code>prototype</code></li><li>实例方法：<code>apply()</code>、<code>bind()</code>、<code>call()</code>、<code>toString()</code>、<code>[Symbol.hasInstance]()</code></li><li>已弃用实例属性：<code>arguments</code>、<code>caller</code></li></ul><h3 id="boolean" tabindex="-1"><code>Boolean</code> <a class="header-anchor" href="#boolean" aria-label="Permalink to &quot;`Boolean`&quot;">​</a></h3><ul><li>构造与转换：<code>Boolean()</code></li><li>实例方法：<code>toString()</code>、<code>valueOf()</code></li></ul><h3 id="symbol" tabindex="-1"><code>Symbol</code> <a class="header-anchor" href="#symbol" aria-label="Permalink to &quot;`Symbol`&quot;">​</a></h3><ul><li>创建：<code>Symbol()</code>，不能使用 <code>new</code></li><li>静态注册表：<code>Symbol.for()</code>、<code>Symbol.keyFor()</code></li><li>知名 Symbol：<code>Symbol.asyncDispose</code>、<code>Symbol.asyncIterator</code>、<code>Symbol.dispose</code>、<code>Symbol.hasInstance</code>、<code>Symbol.isConcatSpreadable</code>、<code>Symbol.iterator</code>、<code>Symbol.match</code>、<code>Symbol.matchAll</code>、<code>Symbol.replace</code>、<code>Symbol.search</code>、<code>Symbol.species</code>、<code>Symbol.split</code>、<code>Symbol.toPrimitive</code>、<code>Symbol.toStringTag</code>、<code>Symbol.unscopables</code></li><li>实例属性：<code>description</code></li><li>实例方法：<code>toString()</code>、<code>valueOf()</code>、<code>[Symbol.toPrimitive]()</code></li></ul><h2 id="错误对象" tabindex="-1">错误对象 <a class="header-anchor" href="#错误对象" aria-label="Permalink to &quot;错误对象&quot;">​</a></h2><h3 id="错误类型" tabindex="-1">错误类型 <a class="header-anchor" href="#错误类型" aria-label="Permalink to &quot;错误类型&quot;">​</a></h3><ul><li><code>Error</code></li><li><code>AggregateError</code></li><li><code>EvalError</code></li><li><code>RangeError</code></li><li><code>ReferenceError</code></li><li><code>SuppressedError</code></li><li><code>SyntaxError</code></li><li><code>TypeError</code></li><li><code>URIError</code></li></ul><h3 id="错误成员" tabindex="-1">错误成员 <a class="header-anchor" href="#错误成员" aria-label="Permalink to &quot;错误成员&quot;">​</a></h3><ul><li><code>Error.isError()</code>：跨 Realm 判断错误对象</li><li>通用实例属性：<code>name</code>、<code>message</code>、<code>cause</code></li><li>通用实例方法：<code>toString()</code></li><li><code>AggregateError</code> 实例属性：<code>errors</code></li><li><code>SuppressedError</code> 实例属性：<code>error</code>、<code>suppressed</code></li><li><code>stack</code>、<code>Error.captureStackTrace()</code>、<code>Error.stackTraceLimit</code> 等属于非标准运行时扩展，不属于 ECMAScript 标准 API</li></ul><p><code>EvalError</code> 保留用于兼容，但现代引擎通常不再主动抛出它。</p><h2 id="数值与数学" tabindex="-1">数值与数学 <a class="header-anchor" href="#数值与数学" aria-label="Permalink to &quot;数值与数学&quot;">​</a></h2><h3 id="number" tabindex="-1"><code>Number</code> <a class="header-anchor" href="#number" aria-label="Permalink to &quot;`Number`&quot;">​</a></h3><ul><li>构造与转换：<code>Number()</code></li><li>静态常量：<code>Number.EPSILON</code>、<code>Number.MAX_SAFE_INTEGER</code>、<code>Number.MAX_VALUE</code>、<code>Number.MIN_SAFE_INTEGER</code>、<code>Number.MIN_VALUE</code>、<code>Number.NaN</code>、<code>Number.NEGATIVE_INFINITY</code>、<code>Number.POSITIVE_INFINITY</code></li><li>静态判断：<code>Number.isFinite()</code>、<code>Number.isInteger()</code>、<code>Number.isNaN()</code>、<code>Number.isSafeInteger()</code></li><li>静态解析：<code>Number.parseFloat()</code>、<code>Number.parseInt()</code></li><li>实例格式化：<code>toExponential()</code>、<code>toFixed()</code>、<code>toLocaleString()</code>、<code>toPrecision()</code>、<code>toString()</code></li><li>实例取值：<code>valueOf()</code></li></ul><h3 id="bigint" tabindex="-1"><code>BigInt</code> <a class="header-anchor" href="#bigint" aria-label="Permalink to &quot;`BigInt`&quot;">​</a></h3><ul><li>创建与转换：<code>BigInt()</code>，不能使用 <code>new</code></li><li>静态截断：<code>BigInt.asIntN()</code>、<code>BigInt.asUintN()</code></li><li>实例方法：<code>toLocaleString()</code>、<code>toString()</code>、<code>valueOf()</code></li></ul><h3 id="math" tabindex="-1"><code>Math</code> <a class="header-anchor" href="#math" aria-label="Permalink to &quot;`Math`&quot;">​</a></h3><ul><li>常量：<code>Math.E</code>、<code>Math.LN10</code>、<code>Math.LN2</code>、<code>Math.LOG10E</code>、<code>Math.LOG2E</code>、<code>Math.PI</code>、<code>Math.SQRT1_2</code>、<code>Math.SQRT2</code></li><li>基本计算：<code>Math.abs()</code>、<code>Math.cbrt()</code>、<code>Math.hypot()</code>、<code>Math.max()</code>、<code>Math.min()</code>、<code>Math.pow()</code>、<code>Math.sign()</code>、<code>Math.sqrt()</code>、<code>Math.sumPrecise()</code></li><li>取整：<code>Math.ceil()</code>、<code>Math.floor()</code>、<code>Math.round()</code>、<code>Math.trunc()</code></li><li>浮点与整数：<code>Math.clz32()</code>、<code>Math.f16round()</code>、<code>Math.fround()</code>、<code>Math.imul()</code></li><li>指数与对数：<code>Math.exp()</code>、<code>Math.expm1()</code>、<code>Math.log()</code>、<code>Math.log10()</code>、<code>Math.log1p()</code>、<code>Math.log2()</code></li><li>三角函数：<code>Math.acos()</code>、<code>Math.acosh()</code>、<code>Math.asin()</code>、<code>Math.asinh()</code>、<code>Math.atan()</code>、<code>Math.atan2()</code>、<code>Math.atanh()</code>、<code>Math.cos()</code>、<code>Math.cosh()</code>、<code>Math.sin()</code>、<code>Math.sinh()</code>、<code>Math.tan()</code>、<code>Math.tanh()</code></li><li>随机数：<code>Math.random()</code></li></ul><p><code>Math.random()</code> 不适合密码学、安全令牌或不可预测标识符。</p><h2 id="日期与时间" tabindex="-1">日期与时间 <a class="header-anchor" href="#日期与时间" aria-label="Permalink to &quot;日期与时间&quot;">​</a></h2><h3 id="date" tabindex="-1"><code>Date</code> <a class="header-anchor" href="#date" aria-label="Permalink to &quot;`Date`&quot;">​</a></h3><ul><li>构造：<code>Date()</code>、<code>new Date()</code></li><li>静态方法：<code>Date.now()</code>、<code>Date.parse()</code>、<code>Date.UTC()</code></li><li>本地时间读取：<code>getDate()</code>、<code>getDay()</code>、<code>getFullYear()</code>、<code>getHours()</code>、<code>getMilliseconds()</code>、<code>getMinutes()</code>、<code>getMonth()</code>、<code>getSeconds()</code>、<code>getTime()</code>、<code>getTimezoneOffset()</code></li><li>UTC 时间读取：<code>getUTCDate()</code>、<code>getUTCDay()</code>、<code>getUTCFullYear()</code>、<code>getUTCHours()</code>、<code>getUTCMilliseconds()</code>、<code>getUTCMinutes()</code>、<code>getUTCMonth()</code>、<code>getUTCSeconds()</code></li><li>本地时间修改：<code>setDate()</code>、<code>setFullYear()</code>、<code>setHours()</code>、<code>setMilliseconds()</code>、<code>setMinutes()</code>、<code>setMonth()</code>、<code>setSeconds()</code>、<code>setTime()</code></li><li>UTC 时间修改：<code>setUTCDate()</code>、<code>setUTCFullYear()</code>、<code>setUTCHours()</code>、<code>setUTCMilliseconds()</code>、<code>setUTCMinutes()</code>、<code>setUTCMonth()</code>、<code>setUTCSeconds()</code></li><li>字符串与序列化：<code>toDateString()</code>、<code>toISOString()</code>、<code>toJSON()</code>、<code>toLocaleDateString()</code>、<code>toLocaleString()</code>、<code>toLocaleTimeString()</code>、<code>toString()</code>、<code>toTimeString()</code>、<code>toUTCString()</code>、<code>valueOf()</code>、<code>[Symbol.toPrimitive]()</code></li><li>已弃用：<code>getYear()</code>、<code>setYear()</code>、<code>toGMTString()</code></li></ul><h3 id="temporal" tabindex="-1"><code>Temporal</code> <a class="header-anchor" href="#temporal" aria-label="Permalink to &quot;`Temporal`&quot;">​</a></h3><p><code>Temporal</code> 提供纳秒精度、明确的时区与日历模型。它已经进入当前标准，但运行时支持仍可能不完整。</p><h4 id="temporal-duration" tabindex="-1"><code>Temporal.Duration</code> <a class="header-anchor" href="#temporal-duration" aria-label="Permalink to &quot;`Temporal.Duration`&quot;">​</a></h4><ul><li>静态：<code>Temporal.Duration.compare()</code>、<code>Temporal.Duration.from()</code></li><li>实例属性：<code>blank</code>、<code>days</code>、<code>hours</code>、<code>microseconds</code>、<code>milliseconds</code>、<code>minutes</code>、<code>months</code>、<code>nanoseconds</code>、<code>seconds</code>、<code>sign</code>、<code>weeks</code>、<code>years</code></li><li>实例方法：<code>abs()</code>、<code>add()</code>、<code>negated()</code>、<code>round()</code>、<code>subtract()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toString()</code>、<code>total()</code>、<code>valueOf()</code>、<code>with()</code></li></ul><h4 id="temporal-instant" tabindex="-1"><code>Temporal.Instant</code> <a class="header-anchor" href="#temporal-instant" aria-label="Permalink to &quot;`Temporal.Instant`&quot;">​</a></h4><ul><li>静态：<code>Temporal.Instant.compare()</code>、<code>Temporal.Instant.from()</code>、<code>Temporal.Instant.fromEpochMilliseconds()</code>、<code>Temporal.Instant.fromEpochNanoseconds()</code></li><li>实例属性：<code>epochMilliseconds</code>、<code>epochNanoseconds</code></li><li>实例方法：<code>add()</code>、<code>equals()</code>、<code>round()</code>、<code>since()</code>、<code>subtract()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toString()</code>、<code>toZonedDateTimeISO()</code>、<code>until()</code>、<code>valueOf()</code></li></ul><h4 id="temporal-plaindate" tabindex="-1"><code>Temporal.PlainDate</code> <a class="header-anchor" href="#temporal-plaindate" aria-label="Permalink to &quot;`Temporal.PlainDate`&quot;">​</a></h4><ul><li>静态：<code>Temporal.PlainDate.compare()</code>、<code>Temporal.PlainDate.from()</code></li><li>实例属性：<code>calendarId</code>、<code>day</code>、<code>dayOfWeek</code>、<code>dayOfYear</code>、<code>daysInMonth</code>、<code>daysInWeek</code>、<code>daysInYear</code>、<code>era</code>、<code>eraYear</code>、<code>inLeapYear</code>、<code>month</code>、<code>monthCode</code>、<code>monthsInYear</code>、<code>weekOfYear</code>、<code>year</code>、<code>yearOfWeek</code></li><li>实例方法：<code>add()</code>、<code>equals()</code>、<code>since()</code>、<code>subtract()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toPlainDateTime()</code>、<code>toPlainMonthDay()</code>、<code>toPlainYearMonth()</code>、<code>toString()</code>、<code>toZonedDateTime()</code>、<code>until()</code>、<code>valueOf()</code>、<code>with()</code>、<code>withCalendar()</code></li></ul><h4 id="temporal-plaindatetime" tabindex="-1"><code>Temporal.PlainDateTime</code> <a class="header-anchor" href="#temporal-plaindatetime" aria-label="Permalink to &quot;`Temporal.PlainDateTime`&quot;">​</a></h4><ul><li>静态：<code>Temporal.PlainDateTime.compare()</code>、<code>Temporal.PlainDateTime.from()</code></li><li>日期属性：<code>calendarId</code>、<code>day</code>、<code>dayOfWeek</code>、<code>dayOfYear</code>、<code>daysInMonth</code>、<code>daysInWeek</code>、<code>daysInYear</code>、<code>era</code>、<code>eraYear</code>、<code>inLeapYear</code>、<code>month</code>、<code>monthCode</code>、<code>monthsInYear</code>、<code>weekOfYear</code>、<code>year</code>、<code>yearOfWeek</code></li><li>时间属性：<code>hour</code>、<code>microsecond</code>、<code>millisecond</code>、<code>minute</code>、<code>nanosecond</code>、<code>second</code></li><li>实例方法：<code>add()</code>、<code>equals()</code>、<code>round()</code>、<code>since()</code>、<code>subtract()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toPlainDate()</code>、<code>toPlainTime()</code>、<code>toString()</code>、<code>toZonedDateTime()</code>、<code>until()</code>、<code>valueOf()</code>、<code>with()</code>、<code>withCalendar()</code>、<code>withPlainTime()</code></li></ul><h4 id="temporal-plainmonthday" tabindex="-1"><code>Temporal.PlainMonthDay</code> <a class="header-anchor" href="#temporal-plainmonthday" aria-label="Permalink to &quot;`Temporal.PlainMonthDay`&quot;">​</a></h4><ul><li>静态：<code>Temporal.PlainMonthDay.from()</code></li><li>实例属性：<code>calendarId</code>、<code>day</code>、<code>monthCode</code></li><li>实例方法：<code>equals()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toPlainDate()</code>、<code>toString()</code>、<code>valueOf()</code>、<code>with()</code></li></ul><h4 id="temporal-plaintime" tabindex="-1"><code>Temporal.PlainTime</code> <a class="header-anchor" href="#temporal-plaintime" aria-label="Permalink to &quot;`Temporal.PlainTime`&quot;">​</a></h4><ul><li>静态：<code>Temporal.PlainTime.compare()</code>、<code>Temporal.PlainTime.from()</code></li><li>实例属性：<code>hour</code>、<code>microsecond</code>、<code>millisecond</code>、<code>minute</code>、<code>nanosecond</code>、<code>second</code></li><li>实例方法：<code>add()</code>、<code>equals()</code>、<code>round()</code>、<code>since()</code>、<code>subtract()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toString()</code>、<code>until()</code>、<code>valueOf()</code>、<code>with()</code></li></ul><h4 id="temporal-plainyearmonth" tabindex="-1"><code>Temporal.PlainYearMonth</code> <a class="header-anchor" href="#temporal-plainyearmonth" aria-label="Permalink to &quot;`Temporal.PlainYearMonth`&quot;">​</a></h4><ul><li>静态：<code>Temporal.PlainYearMonth.compare()</code>、<code>Temporal.PlainYearMonth.from()</code></li><li>实例属性：<code>calendarId</code>、<code>daysInMonth</code>、<code>daysInYear</code>、<code>era</code>、<code>eraYear</code>、<code>inLeapYear</code>、<code>month</code>、<code>monthCode</code>、<code>monthsInYear</code>、<code>year</code></li><li>实例方法：<code>add()</code>、<code>equals()</code>、<code>since()</code>、<code>subtract()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toPlainDate()</code>、<code>toString()</code>、<code>until()</code>、<code>valueOf()</code>、<code>with()</code></li></ul><h4 id="temporal-zoneddatetime" tabindex="-1"><code>Temporal.ZonedDateTime</code> <a class="header-anchor" href="#temporal-zoneddatetime" aria-label="Permalink to &quot;`Temporal.ZonedDateTime`&quot;">​</a></h4><ul><li>静态：<code>Temporal.ZonedDateTime.compare()</code>、<code>Temporal.ZonedDateTime.from()</code></li><li>日期属性：<code>calendarId</code>、<code>day</code>、<code>dayOfWeek</code>、<code>dayOfYear</code>、<code>daysInMonth</code>、<code>daysInWeek</code>、<code>daysInYear</code>、<code>era</code>、<code>eraYear</code>、<code>inLeapYear</code>、<code>month</code>、<code>monthCode</code>、<code>monthsInYear</code>、<code>weekOfYear</code>、<code>year</code>、<code>yearOfWeek</code></li><li>时间与时区属性：<code>epochMilliseconds</code>、<code>epochNanoseconds</code>、<code>hour</code>、<code>hoursInDay</code>、<code>microsecond</code>、<code>millisecond</code>、<code>minute</code>、<code>nanosecond</code>、<code>offset</code>、<code>offsetNanoseconds</code>、<code>second</code>、<code>timeZoneId</code></li><li>实例方法：<code>add()</code>、<code>equals()</code>、<code>getTimeZoneTransition()</code>、<code>round()</code>、<code>since()</code>、<code>startOfDay()</code>、<code>subtract()</code>、<code>toInstant()</code>、<code>toJSON()</code>、<code>toLocaleString()</code>、<code>toPlainDate()</code>、<code>toPlainDateTime()</code>、<code>toPlainTime()</code>、<code>toString()</code>、<code>until()</code>、<code>valueOf()</code>、<code>with()</code>、<code>withCalendar()</code>、<code>withPlainTime()</code>、<code>withTimeZone()</code></li></ul><h4 id="temporal-now" tabindex="-1"><code>Temporal.Now</code> <a class="header-anchor" href="#temporal-now" aria-label="Permalink to &quot;`Temporal.Now`&quot;">​</a></h4><ul><li><code>Temporal.Now.instant()</code></li><li><code>Temporal.Now.plainDateISO()</code></li><li><code>Temporal.Now.plainDateTimeISO()</code></li><li><code>Temporal.Now.plainTimeISO()</code></li><li><code>Temporal.Now.timeZoneId()</code></li><li><code>Temporal.Now.zonedDateTimeISO()</code></li></ul><h2 id="文本处理" tabindex="-1">文本处理 <a class="header-anchor" href="#文本处理" aria-label="Permalink to &quot;文本处理&quot;">​</a></h2><h3 id="string" tabindex="-1"><code>String</code> <a class="header-anchor" href="#string" aria-label="Permalink to &quot;`String`&quot;">​</a></h3><ul><li>构造与转换：<code>String()</code></li><li>静态方法：<code>String.fromCharCode()</code>、<code>String.fromCodePoint()</code>、<code>String.raw()</code></li><li>实例属性：<code>length</code></li><li>定位与字符：<code>at()</code>、<code>charAt()</code>、<code>charCodeAt()</code>、<code>codePointAt()</code></li><li>查询：<code>endsWith()</code>、<code>includes()</code>、<code>indexOf()</code>、<code>lastIndexOf()</code>、<code>localeCompare()</code>、<code>startsWith()</code></li><li>匹配与替换：<code>match()</code>、<code>matchAll()</code>、<code>replace()</code>、<code>replaceAll()</code>、<code>search()</code>、<code>split()</code></li><li>截取与组合：<code>concat()</code>、<code>slice()</code>、<code>substring()</code></li><li>格式与填充：<code>normalize()</code>、<code>padEnd()</code>、<code>padStart()</code>、<code>repeat()</code>、<code>toLocaleLowerCase()</code>、<code>toLocaleUpperCase()</code>、<code>toLowerCase()</code>、<code>toUpperCase()</code>、<code>trim()</code>、<code>trimEnd()</code>、<code>trimStart()</code></li><li>Unicode 完整性：<code>isWellFormed()</code>、<code>toWellFormed()</code></li><li>转换与迭代：<code>toString()</code>、<code>valueOf()</code>、<code>[Symbol.iterator]()</code></li><li>别名：<code>trimLeft()</code>、<code>trimRight()</code></li><li>已弃用：<code>anchor()</code>、<code>big()</code>、<code>blink()</code>、<code>bold()</code>、<code>fixed()</code>、<code>fontcolor()</code>、<code>fontsize()</code>、<code>italics()</code>、<code>link()</code>、<code>small()</code>、<code>strike()</code>、<code>sub()</code>、<code>substr()</code>、<code>sup()</code></li></ul><h3 id="regexp" tabindex="-1"><code>RegExp</code> <a class="header-anchor" href="#regexp" aria-label="Permalink to &quot;`RegExp`&quot;">​</a></h3><ul><li>构造：<code>RegExp()</code></li><li>静态方法：<code>RegExp.escape()</code></li><li>实例状态：<code>lastIndex</code></li><li>实例标志属性：<code>dotAll</code>、<code>flags</code>、<code>global</code>、<code>hasIndices</code>、<code>ignoreCase</code>、<code>multiline</code>、<code>sticky</code>、<code>unicode</code>、<code>unicodeSets</code></li><li>实例模式属性：<code>source</code></li><li>实例方法：<code>exec()</code>、<code>test()</code>、<code>toString()</code></li><li>协议方法：<code>[Symbol.match]()</code>、<code>[Symbol.matchAll]()</code>、<code>[Symbol.replace]()</code>、<code>[Symbol.search]()</code>、<code>[Symbol.split]()</code></li><li>已弃用：<code>compile()</code></li></ul><p><code>RegExp.$1</code> 到 <code>RegExp.$9</code>、<code>RegExp.input</code>、<code>RegExp.lastMatch</code> 等属于非标准遗留扩展，不作为标准 API 推荐。</p><h2 id="索引集合" tabindex="-1">索引集合 <a class="header-anchor" href="#索引集合" aria-label="Permalink to &quot;索引集合&quot;">​</a></h2><h3 id="array" tabindex="-1"><code>Array</code> <a class="header-anchor" href="#array" aria-label="Permalink to &quot;`Array`&quot;">​</a></h3><ul><li>静态：<code>Array.from()</code>、<code>Array.fromAsync()</code>、<code>Array.isArray()</code>、<code>Array.of()</code></li><li>实例属性：<code>length</code></li><li>访问与查询：<code>at()</code>、<code>find()</code>、<code>findIndex()</code>、<code>findLast()</code>、<code>findLastIndex()</code>、<code>includes()</code>、<code>indexOf()</code>、<code>lastIndexOf()</code></li><li>增删与修改：<code>copyWithin()</code>、<code>fill()</code>、<code>pop()</code>、<code>push()</code>、<code>reverse()</code>、<code>shift()</code>、<code>sort()</code>、<code>splice()</code>、<code>unshift()</code></li><li>不可变替代：<code>toReversed()</code>、<code>toSorted()</code>、<code>toSpliced()</code>、<code>with()</code></li><li>转换与组合：<code>concat()</code>、<code>filter()</code>、<code>flat()</code>、<code>flatMap()</code>、<code>map()</code>、<code>slice()</code></li><li>判断与聚合：<code>every()</code>、<code>reduce()</code>、<code>reduceRight()</code>、<code>some()</code></li><li>遍历：<code>entries()</code>、<code>forEach()</code>、<code>keys()</code>、<code>values()</code>、<code>[Symbol.iterator]()</code></li><li>字符串转换：<code>join()</code>、<code>toLocaleString()</code>、<code>toString()</code></li></ul><h3 id="typedarray" tabindex="-1">TypedArray <a class="header-anchor" href="#typedarray" aria-label="Permalink to &quot;TypedArray&quot;">​</a></h3><p>具体类型：</p><ul><li>整数：<code>Int8Array</code>、<code>Uint8Array</code>、<code>Uint8ClampedArray</code>、<code>Int16Array</code>、<code>Uint16Array</code>、<code>Int32Array</code>、<code>Uint32Array</code></li><li>大整数：<code>BigInt64Array</code>、<code>BigUint64Array</code></li><li>浮点数：<code>Float16Array</code>、<code>Float32Array</code>、<code>Float64Array</code></li></ul><p>共享 API：</p><ul><li>静态：<code>TypedArray.from()</code>、<code>TypedArray.of()</code>；各具体类型提供 <code>BYTES_PER_ELEMENT</code></li><li>实例属性：<code>buffer</code>、<code>byteLength</code>、<code>byteOffset</code>、<code>length</code>、<code>BYTES_PER_ELEMENT</code></li><li>访问与查询：<code>at()</code>、<code>find()</code>、<code>findIndex()</code>、<code>findLast()</code>、<code>findLastIndex()</code>、<code>includes()</code>、<code>indexOf()</code>、<code>lastIndexOf()</code></li><li>修改：<code>copyWithin()</code>、<code>fill()</code>、<code>reverse()</code>、<code>set()</code>、<code>sort()</code></li><li>不可变替代：<code>toReversed()</code>、<code>toSorted()</code>、<code>with()</code></li><li>转换：<code>filter()</code>、<code>map()</code>、<code>slice()</code>、<code>subarray()</code></li><li>判断与聚合：<code>every()</code>、<code>reduce()</code>、<code>reduceRight()</code>、<code>some()</code></li><li>遍历：<code>entries()</code>、<code>forEach()</code>、<code>keys()</code>、<code>values()</code>、<code>[Symbol.iterator]()</code></li><li>字符串转换：<code>join()</code>、<code>toLocaleString()</code>、<code>toString()</code></li></ul><h3 id="uint8array-编解码" tabindex="-1"><code>Uint8Array</code> 编解码 <a class="header-anchor" href="#uint8array-编解码" aria-label="Permalink to &quot;`Uint8Array` 编解码&quot;">​</a></h3><ul><li>静态创建：<code>Uint8Array.fromBase64()</code>、<code>Uint8Array.fromHex()</code></li><li>实例编码：<code>toBase64()</code>、<code>toHex()</code></li><li>写入现有缓冲区：<code>setFromBase64()</code>、<code>setFromHex()</code></li></ul><h2 id="键值集合" tabindex="-1">键值集合 <a class="header-anchor" href="#键值集合" aria-label="Permalink to &quot;键值集合&quot;">​</a></h2><h3 id="map" tabindex="-1"><code>Map</code> <a class="header-anchor" href="#map" aria-label="Permalink to &quot;`Map`&quot;">​</a></h3><ul><li>静态：<code>Map.groupBy()</code></li><li>实例属性：<code>size</code></li><li>实例方法：<code>clear()</code>、<code>delete()</code>、<code>entries()</code>、<code>forEach()</code>、<code>get()</code>、<code>getOrInsert()</code>、<code>getOrInsertComputed()</code>、<code>has()</code>、<code>keys()</code>、<code>set()</code>、<code>values()</code>、<code>[Symbol.iterator]()</code></li></ul><h3 id="set" tabindex="-1"><code>Set</code> <a class="header-anchor" href="#set" aria-label="Permalink to &quot;`Set`&quot;">​</a></h3><ul><li>实例属性：<code>size</code></li><li>基本方法：<code>add()</code>、<code>clear()</code>、<code>delete()</code>、<code>has()</code></li><li>集合运算：<code>difference()</code>、<code>intersection()</code>、<code>symmetricDifference()</code>、<code>union()</code></li><li>集合关系：<code>isDisjointFrom()</code>、<code>isSubsetOf()</code>、<code>isSupersetOf()</code></li><li>遍历：<code>entries()</code>、<code>forEach()</code>、<code>keys()</code>、<code>values()</code>、<code>[Symbol.iterator]()</code></li></ul><h3 id="weakmap" tabindex="-1"><code>WeakMap</code> <a class="header-anchor" href="#weakmap" aria-label="Permalink to &quot;`WeakMap`&quot;">​</a></h3><ul><li>实例方法：<code>delete()</code>、<code>get()</code>、<code>getOrInsert()</code>、<code>getOrInsertComputed()</code>、<code>has()</code>、<code>set()</code></li></ul><h3 id="weakset" tabindex="-1"><code>WeakSet</code> <a class="header-anchor" href="#weakset" aria-label="Permalink to &quot;`WeakSet`&quot;">​</a></h3><ul><li>实例方法：<code>add()</code>、<code>delete()</code>、<code>has()</code></li></ul><p>弱集合不可枚举，也没有 <code>size</code> 或 <code>clear()</code>。其设计目标是避免集合本身阻止对象被垃圾回收。</p><h2 id="二进制与结构化数据" tabindex="-1">二进制与结构化数据 <a class="header-anchor" href="#二进制与结构化数据" aria-label="Permalink to &quot;二进制与结构化数据&quot;">​</a></h2><h3 id="arraybuffer" tabindex="-1"><code>ArrayBuffer</code> <a class="header-anchor" href="#arraybuffer" aria-label="Permalink to &quot;`ArrayBuffer`&quot;">​</a></h3><ul><li>静态：<code>ArrayBuffer.isView()</code></li><li>实例属性：<code>byteLength</code>、<code>detached</code>、<code>maxByteLength</code>、<code>resizable</code></li><li>实例方法：<code>resize()</code>、<code>slice()</code>、<code>transfer()</code>、<code>transferToFixedLength()</code></li></ul><h3 id="sharedarraybuffer" tabindex="-1"><code>SharedArrayBuffer</code> <a class="header-anchor" href="#sharedarraybuffer" aria-label="Permalink to &quot;`SharedArrayBuffer`&quot;">​</a></h3><ul><li>实例属性：<code>byteLength</code>、<code>growable</code>、<code>maxByteLength</code></li><li>实例方法：<code>grow()</code>、<code>slice()</code></li></ul><h3 id="dataview" tabindex="-1"><code>DataView</code> <a class="header-anchor" href="#dataview" aria-label="Permalink to &quot;`DataView`&quot;">​</a></h3><ul><li>实例属性：<code>buffer</code>、<code>byteLength</code>、<code>byteOffset</code></li><li>读取：<code>getBigInt64()</code>、<code>getBigUint64()</code>、<code>getFloat16()</code>、<code>getFloat32()</code>、<code>getFloat64()</code>、<code>getInt8()</code>、<code>getInt16()</code>、<code>getInt32()</code>、<code>getUint8()</code>、<code>getUint16()</code>、<code>getUint32()</code></li><li>写入：<code>setBigInt64()</code>、<code>setBigUint64()</code>、<code>setFloat16()</code>、<code>setFloat32()</code>、<code>setFloat64()</code>、<code>setInt8()</code>、<code>setInt16()</code>、<code>setInt32()</code>、<code>setUint8()</code>、<code>setUint16()</code>、<code>setUint32()</code></li></ul><h3 id="atomics" tabindex="-1"><code>Atomics</code> <a class="header-anchor" href="#atomics" aria-label="Permalink to &quot;`Atomics`&quot;">​</a></h3><ul><li>读取与写入：<code>Atomics.load()</code>、<code>Atomics.store()</code></li><li>原子运算：<code>Atomics.add()</code>、<code>Atomics.and()</code>、<code>Atomics.exchange()</code>、<code>Atomics.or()</code>、<code>Atomics.sub()</code>、<code>Atomics.xor()</code></li><li>比较：<code>Atomics.compareExchange()</code></li><li>等待与通知：<code>Atomics.notify()</code>、<code>Atomics.pause()</code>、<code>Atomics.wait()</code>、<code>Atomics.waitAsync()</code></li><li>判断：<code>Atomics.isLockFree()</code></li></ul><h3 id="json" tabindex="-1"><code>JSON</code> <a class="header-anchor" href="#json" aria-label="Permalink to &quot;`JSON`&quot;">​</a></h3><ul><li><code>JSON.parse()</code></li><li><code>JSON.stringify()</code></li><li><code>JSON.isRawJSON()</code></li><li><code>JSON.rawJSON()</code></li></ul><p><code>JSON</code> 不支持循环引用，也不会自动保留 <code>Map</code>、<code>Set</code>、<code>BigInt</code>、函数、Symbol 和对象原型语义。</p><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="weakref" tabindex="-1"><code>WeakRef</code> <a class="header-anchor" href="#weakref" aria-label="Permalink to &quot;`WeakRef`&quot;">​</a></h3><ul><li>实例方法：<code>deref()</code></li></ul><h3 id="finalizationregistry" tabindex="-1"><code>FinalizationRegistry</code> <a class="header-anchor" href="#finalizationregistry" aria-label="Permalink to &quot;`FinalizationRegistry`&quot;">​</a></h3><ul><li>实例方法：<code>register()</code>、<code>unregister()</code></li></ul><p>垃圾回收时机不可预测。<code>WeakRef</code> 和 <code>FinalizationRegistry</code> 不能用于关键业务流程、资源释放时序或正确性判断。</p><h2 id="迭代、异步与控制抽象" tabindex="-1">迭代、异步与控制抽象 <a class="header-anchor" href="#迭代、异步与控制抽象" aria-label="Permalink to &quot;迭代、异步与控制抽象&quot;">​</a></h2><h3 id="iterator" tabindex="-1"><code>Iterator</code> <a class="header-anchor" href="#iterator" aria-label="Permalink to &quot;`Iterator`&quot;">​</a></h3><ul><li>静态：<code>Iterator.concat()</code>、<code>Iterator.from()</code>、<code>Iterator.zip()</code>、<code>Iterator.zipKeyed()</code></li><li>转换：<code>drop()</code>、<code>filter()</code>、<code>flatMap()</code>、<code>map()</code>、<code>take()</code>、<code>toArray()</code></li><li>消费与判断：<code>every()</code>、<code>find()</code>、<code>forEach()</code>、<code>includes()</code>、<code>reduce()</code>、<code>some()</code></li><li>协议：<code>[Symbol.iterator]()</code>、<code>[Symbol.dispose]()</code></li></ul><h3 id="asynciterator" tabindex="-1"><code>AsyncIterator</code> <a class="header-anchor" href="#asynciterator" aria-label="Permalink to &quot;`AsyncIterator`&quot;">​</a></h3><ul><li>协议：<code>[Symbol.asyncIterator]()</code>、<code>[Symbol.asyncDispose]()</code></li><li><code>AsyncIterator</code> 是异步迭代器原型对象，不应假定所有运行时都将它直接暴露为可构造全局对象</li></ul><h3 id="promise" tabindex="-1"><code>Promise</code> <a class="header-anchor" href="#promise" aria-label="Permalink to &quot;`Promise`&quot;">​</a></h3><ul><li>静态组合：<code>Promise.all()</code>、<code>Promise.allSettled()</code>、<code>Promise.any()</code>、<code>Promise.race()</code></li><li>静态创建：<code>Promise.reject()</code>、<code>Promise.resolve()</code>、<code>Promise.try()</code>、<code>Promise.withResolvers()</code></li><li>实例方法：<code>catch()</code>、<code>finally()</code>、<code>then()</code></li></ul><h3 id="生成器与异步函数对象" tabindex="-1">生成器与异步函数对象 <a class="header-anchor" href="#生成器与异步函数对象" aria-label="Permalink to &quot;生成器与异步函数对象&quot;">​</a></h3><ul><li><code>Generator</code> 实例：<code>next()</code>、<code>return()</code>、<code>throw()</code>、<code>[Symbol.iterator]()</code>、<code>[Symbol.dispose]()</code></li><li><code>AsyncGenerator</code> 实例：<code>next()</code>、<code>return()</code>、<code>throw()</code>、<code>[Symbol.asyncIterator]()</code>、<code>[Symbol.asyncDispose]()</code></li><li>内部构造器：<code>GeneratorFunction</code>、<code>AsyncGeneratorFunction</code>、<code>AsyncFunction</code></li><li>这些内部构造器通常通过函数对象的 <code>constructor</code> 获得，不作为普通全局构造器使用</li></ul><h3 id="disposablestack" tabindex="-1"><code>DisposableStack</code> <a class="header-anchor" href="#disposablestack" aria-label="Permalink to &quot;`DisposableStack`&quot;">​</a></h3><ul><li>实例属性：<code>disposed</code></li><li>注册资源：<code>adopt()</code>、<code>defer()</code>、<code>use()</code></li><li>转移与释放：<code>dispose()</code>、<code>move()</code>、<code>[Symbol.dispose]()</code></li></ul><h3 id="asyncdisposablestack" tabindex="-1"><code>AsyncDisposableStack</code> <a class="header-anchor" href="#asyncdisposablestack" aria-label="Permalink to &quot;`AsyncDisposableStack`&quot;">​</a></h3><ul><li>实例属性：<code>disposed</code></li><li>注册资源：<code>adopt()</code>、<code>defer()</code>、<code>use()</code></li><li>转移与释放：<code>disposeAsync()</code>、<code>move()</code>、<code>[Symbol.asyncDispose]()</code></li></ul><p>显式资源管理还包括语言级 <code>using</code> 和 <code>await using</code> 声明；它们是语法，不属于标准库 API。</p><h2 id="反射与代理" tabindex="-1">反射与代理 <a class="header-anchor" href="#反射与代理" aria-label="Permalink to &quot;反射与代理&quot;">​</a></h2><h3 id="reflect" tabindex="-1"><code>Reflect</code> <a class="header-anchor" href="#reflect" aria-label="Permalink to &quot;`Reflect`&quot;">​</a></h3><ul><li>函数调用与构造：<code>Reflect.apply()</code>、<code>Reflect.construct()</code></li><li>属性操作：<code>Reflect.defineProperty()</code>、<code>Reflect.deleteProperty()</code>、<code>Reflect.get()</code>、<code>Reflect.getOwnPropertyDescriptor()</code>、<code>Reflect.has()</code>、<code>Reflect.ownKeys()</code>、<code>Reflect.set()</code></li><li>原型操作：<code>Reflect.getPrototypeOf()</code>、<code>Reflect.setPrototypeOf()</code></li><li>扩展性：<code>Reflect.isExtensible()</code>、<code>Reflect.preventExtensions()</code></li></ul><h3 id="proxy" tabindex="-1"><code>Proxy</code> <a class="header-anchor" href="#proxy" aria-label="Permalink to &quot;`Proxy`&quot;">​</a></h3><ul><li>创建：<code>new Proxy(target, handler)</code></li><li>静态：<code>Proxy.revocable()</code></li><li>Handler 陷阱：<code>apply()</code>、<code>construct()</code>、<code>defineProperty()</code>、<code>deleteProperty()</code>、<code>get()</code>、<code>getOwnPropertyDescriptor()</code>、<code>getPrototypeOf()</code>、<code>has()</code>、<code>isExtensible()</code>、<code>ownKeys()</code>、<code>preventExtensions()</code>、<code>set()</code>、<code>setPrototypeOf()</code></li></ul><p>Proxy 陷阱必须遵守目标对象的不变量，否则相关操作会抛出 <code>TypeError</code>。</p><h2 id="国际化" tabindex="-1">国际化 <a class="header-anchor" href="#国际化" aria-label="Permalink to &quot;国际化&quot;">​</a></h2><h3 id="intl" tabindex="-1"><code>Intl</code> <a class="header-anchor" href="#intl" aria-label="Permalink to &quot;`Intl`&quot;">​</a></h3><ul><li><code>Intl.getCanonicalLocales()</code></li><li><code>Intl.supportedValuesOf()</code></li></ul><h3 id="intl-collator" tabindex="-1"><code>Intl.Collator</code> <a class="header-anchor" href="#intl-collator" aria-label="Permalink to &quot;`Intl.Collator`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>compare()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-datetimeformat" tabindex="-1"><code>Intl.DateTimeFormat</code> <a class="header-anchor" href="#intl-datetimeformat" aria-label="Permalink to &quot;`Intl.DateTimeFormat`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>format()</code>、<code>formatRange()</code>、<code>formatRangeToParts()</code>、<code>formatToParts()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-displaynames" tabindex="-1"><code>Intl.DisplayNames</code> <a class="header-anchor" href="#intl-displaynames" aria-label="Permalink to &quot;`Intl.DisplayNames`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>of()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-durationformat" tabindex="-1"><code>Intl.DurationFormat</code> <a class="header-anchor" href="#intl-durationformat" aria-label="Permalink to &quot;`Intl.DurationFormat`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>format()</code>、<code>formatToParts()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-listformat" tabindex="-1"><code>Intl.ListFormat</code> <a class="header-anchor" href="#intl-listformat" aria-label="Permalink to &quot;`Intl.ListFormat`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>format()</code>、<code>formatToParts()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-locale" tabindex="-1"><code>Intl.Locale</code> <a class="header-anchor" href="#intl-locale" aria-label="Permalink to &quot;`Intl.Locale`&quot;">​</a></h3><ul><li>标识属性：<code>baseName</code>、<code>language</code>、<code>region</code>、<code>script</code></li><li>Unicode 扩展属性：<code>calendar</code>、<code>caseFirst</code>、<code>collation</code>、<code>firstDayOfWeek</code>、<code>hourCycle</code>、<code>numberingSystem</code>、<code>numeric</code></li><li>可用值属性：<code>calendars</code>、<code>collations</code>、<code>hourCycles</code>、<code>numberingSystems</code>、<code>textInfo</code>、<code>timeZones</code>、<code>weekInfo</code></li><li>实例方法：<code>maximize()</code>、<code>minimize()</code>、<code>toString()</code></li><li>查询方法：<code>getCalendars()</code>、<code>getCollations()</code>、<code>getHourCycles()</code>、<code>getNumberingSystems()</code>、<code>getTextInfo()</code>、<code>getTimeZones()</code>、<code>getWeekInfo()</code></li></ul><h3 id="intl-numberformat" tabindex="-1"><code>Intl.NumberFormat</code> <a class="header-anchor" href="#intl-numberformat" aria-label="Permalink to &quot;`Intl.NumberFormat`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>format()</code>、<code>formatRange()</code>、<code>formatRangeToParts()</code>、<code>formatToParts()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-pluralrules" tabindex="-1"><code>Intl.PluralRules</code> <a class="header-anchor" href="#intl-pluralrules" aria-label="Permalink to &quot;`Intl.PluralRules`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>resolvedOptions()</code>、<code>select()</code>、<code>selectRange()</code></li></ul><h3 id="intl-relativetimeformat" tabindex="-1"><code>Intl.RelativeTimeFormat</code> <a class="header-anchor" href="#intl-relativetimeformat" aria-label="Permalink to &quot;`Intl.RelativeTimeFormat`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>format()</code>、<code>formatToParts()</code>、<code>resolvedOptions()</code></li></ul><h3 id="intl-segmenter" tabindex="-1"><code>Intl.Segmenter</code> <a class="header-anchor" href="#intl-segmenter" aria-label="Permalink to &quot;`Intl.Segmenter`&quot;">​</a></h3><ul><li>静态：<code>supportedLocalesOf()</code></li><li>实例：<code>resolvedOptions()</code>、<code>segment()</code></li><li><code>segment()</code> 返回的 <code>Segments</code>：<code>containing()</code>、<code>[Symbol.iterator]()</code></li><li>分段结果属性：<code>segment</code>、<code>index</code>、<code>input</code>，单词粒度时还包括 <code>isWordLike</code></li></ul><h2 id="兼容性与标准来源" tabindex="-1">兼容性与标准来源 <a class="header-anchor" href="#兼容性与标准来源" aria-label="Permalink to &quot;兼容性与标准来源&quot;">​</a></h2><ul><li><a href="https://tc39.es/ecma262/" target="_blank" rel="noreferrer">ECMAScript 语言规范</a></li><li><a href="https://tc39.es/ecma402/" target="_blank" rel="noreferrer">ECMAScript 国际化 API 规范</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects" target="_blank" rel="noreferrer">MDN 标准内置对象索引</a></li><li><a href="https://github.com/tc39/proposals" target="_blank" rel="noreferrer">TC39 提案列表</a></li></ul><p>当规范、MDN 和某个运行时的实际成员不一致时，应先确认 API 是否已经进入标准，再检查目标运行时的实现版本和兼容性，而不是把单一运行时的反射结果当作标准定义。</p>',149)])])}const p=o(t,[["render",l]]);export{m as __pageData,p as default};
